arguments.command:
python3 << 'EOF'
import pandas as pd

# Find what's at the 1992 position
df_pce = pd.read_excel('/root/ERP-2025-table10.xls', sheet_name=0)

for i in range(4, len(df_pce)):
    year_val = df_pce.iloc[i, 0]
    if pd.isna(year_val):
        continue

    if isinstance(year_val, str):
        year_val_clean = year_val.strip('.')
        if year_val_clean.isdigit():
            year = int(year_val_clean)
            if 1990 <= year <= 1995:
                print(f"Row {i}: Year={year}, PCE={df_pce.iloc[i, 1]}")

EOF

